import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<CurrencyModel>> _currencyListFuture;
  late final AnimationController _fadeController;
  late final Animation<double> _fadeAnimation;

  List<CurrencyModel> _allCurrencies = [];
  String _searchQuery = '';

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadInitialPage();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.removeListener(_onFilteredChanged);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  // --- Filtering ----------------------------------------------------------
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
    _fadeAnimation = _tween.animate(_fadeController);
    _filteredCurrenciesNotifier = ValueNotifier<List<CurrencyModel>>([]);
    _filteredCurrenciesNotifier.addListener(_onFilteredChanged);
  }

  void _onFilteredChanged() {
    if (mounted) setState(() {});
  }

  // --- Data loading -------------------------------------------------------
  Future<void> _loadInitialPage() async {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository
        .fetchRates(const CurrencyPageRequest(base: 'USD', page: 0))
        .then((CurrencyPage page) {
      setState(() {
        _allCurrencies = page.items;
        _currentPage = page.page + 1;
        _hasMore = page.hasMore;
        _applyFilter();
        currencyRepository.saveCurrencyList(_allCurrencies);
      });

      if (_fadeController.status != AnimationStatus.forward) {
        _fadeController.forward();
      }

      return _allCurrencies;
    }).catchError((_) {
      setState(() => _filteredCurrenciesNotifier.value = []);
      return <CurrencyModel>[];
    });
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();

    try {
      final page = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: _currentPage),
      );

      if (!mounted) return;

      setState(() {
        _allCurrencies.addAll(page.items);
        _hasMore = page.hasMore;
        _applyFilter();
        currencyRepository.saveCurrencyList(_allCurrencies);
      });
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  void _applyFilter() {
    final String lowerQuery = _searchQuery.toLowerCase();
    final List<CurrencyModel> result;

    if (_searchQuery.isEmpty) {
      result = List.unmodifiable(_allCurrencies);
    } else {
      result = _allCurrencies
          .where((currency) =>
              currency.name.toLowerCase().contains(lowerQuery) ||
              currency.symbol.toLowerCase().contains(lowerQuery))
          .toList(growable: false);
    }

    _filteredCurrenciesNotifier.value = result;
  }

  void _filterCurrencies(String query) {
    setState(() => _searchQuery = query);
    _applyFilter();
  }

  // --- Lifecycle ----------------------------------------------------------
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _loadInitialPage();
    }
  }

  // --- Build --------------------------------------------------------------
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext ctx, AsyncSnapshot<List<CurrencyModel>> snap) {
          final data = snap.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeAnimation,
            child: Column(
              children: [
                Padding(
                  padding:
                      const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (ctx, listData, _) {
                      return ListView.builder(
                        itemCount: listData.length + (_hasMore ? 1 : 0),
                        itemBuilder: (ctx, index) {
                          if (index >= listData.length) {
                            // Show "show more" button / loading indicator
                            if (_isLoadingMore) {
                              return const Padding(
                                padding: EdgeInsets.all(16.0),
                                child: Center(child: CircularProgressIndicator()),
                              );
                            }

                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 8),
                              child: Center(
                                child: ElevatedButton(
                                  onPressed: _loadMore,
                                  child: Text(context.loc.showMoreLabel),
                                ),
                              ),
                            );
                          }

                          final currency = listData[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0
                                ? const EdgeInsets.only(top: 20)
                                : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
