    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  void _applyFilter() {
    final String lowerQuery = _searchQuery.toLowerCase();
    final List<CurrencyModel> result;

    if (_searchQuery.isEmpty) {
      result = List.unmodifiable(_allCurrencies);
    } else {
      result = _allCurrencies
          .where((currency) =>
              currency.name.toLowerCase().contains(lowerQuery) ||
              currency.symbol.toLowerCase().contains(lowerQuery))
          .toList(growable: false);
    }

    _filteredCurrenciesNotifier.value = result;
  }

  void _filterCurrencies(String query) {
    setState(() => _searchQuery = query);
    _applyFilter();
  }

  // --- Lifecycle ----------------------------------------------------------
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _loadInitialPage();
    }
  }

  // --- Build --------------------------------------------------------------
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext ctx, AsyncSnapshot<List<CurrencyModel>> snap) {
          final data = snap.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeAnimation,
            child: Column(
              children: [
                Padding(
                  padding:
                      const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (ctx, listData, _) {
                      return ListView.builder(
                        itemCount: listData.length + (_hasMore ? 1 : 0),
                        itemBuilder: (ctx, index) {
                          if (index >= listData.length) {
                            // Show "show more" button / loading indicator
                            if (_isLoadingMore) {
                              return const Padding(
                                padding: EdgeInsets.all(16.0),
                                child: Center(child: CircularProgressIndicator()),
                              );
                            }

                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 8),
                              child: Center(
                                child: ElevatedButton(
                                  onPressed: _loadMore,
                                  child: Text(context.loc.showMoreLabel),
                                ),
                              ),
                            );
                          }

                          final currency = listData[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0
                                ? const EdgeInsets.only(top: 20)
                                : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
